/* The Edinburgh Fringe's planner catalogue, read off its three wire files and
 * joined: the compact catalogue (shows.min.json, packed by scraper/normalize.py),
 * the shared lookups (venues.json) and the availability sidecar
 * (availability.min.json). ../plan/lib/hydrate.js does the joining; this module
 * owns fetching the three and refusing a pair that belongs to different
 * generations. Both planners read Edinburgh through it: the Fringe planner
 * (plan/plan.js) and the festival planner, via shared/festival-catalogue.js.
 *
 * Whether a cached copy of each may be reused is decided by data/manifest.json
 * (shared/data-cache.js): a file is re-fetched exactly when its published hash
 * has moved. That is why availability is split out of the catalogue — the
 * catalogue is the bulkiest blocking download and carries nothing that changes
 * through the day, so it is only re-downloaded when a show is actually added or
 * changed, while availability's own hash moves with the ticket refresh.
 */

import { cachedFetchJson, evictCached, fetchManifest } from "./data-cache.js";
import { rehydrateShows, joinFingerprint } from "../plan/lib/hydrate.js";

/* What each file has to look like before we'll build a planner out of it.
 *
 * These exist because a cached copy from an older generation of a file parses
 * perfectly and then joins to nothing — no exception, no console line, just a
 * planner quietly reporting that the whole festival is unavailable (#309). The
 * sidecar has carried a `v` for this all along; nothing was reading it. Kept
 * deliberately shallow: enough to tell "this is the file I think it is" from
 * "this is something else", not a schema validator. */
const isCatalogue = (d) => Array.isArray(d) && d.length > 0;
const isLookups = (d) => Boolean(d) && typeof d.venues === "object" && d.venues !== null;
const isAvailabilitySidecar = (d) =>
  Boolean(d) && d.v === 1 && Array.isArray(d.ts) && d.ts.length > 0 &&
  Boolean(d.a) && typeof d.a === "object" && Object.keys(d.a).length > 0;

/* How much of the catalogue must come back with a ticket status before we are
 * willing to draw it.
 *
 * A cached catalogue can still be joined to a sidecar from another publish
 * (see loadEdfringeWire), and a few misses are the honest cost of that: a show
 * that added or dropped a date since the catalogue was packed finds no status,
 * which is exactly what the date-and-time naming scheme was designed to do.
 * Real drift between publishes is a fraction of a percent.
 *
 * A systematic key change is a different animal. #274 corrected every start
 * time by an hour, and the next day's sidecar matched 6% of the previous day's
 * catalogue — 94% of the festival status-unknown, drawn as unavailable (#309).
 * Nothing between 6% and 99% is a state we can tell a coherent story about, so
 * the line sits where it separates drift from breakage rather than where it
 * splits the difference. */
const MIN_STATUS_COVERAGE = 0.9;

/**
 * Do these two files describe the same festival?
 *
 * Two independent answers, because they fail in different places. The
 * fingerprint is exact and cheap and settles it outright — but only for a
 * sidecar new enough to carry one, which a cached copy predating that field
 * won't. Coverage is the fallback: approximate, but it reads the join itself
 * rather than a claim about it, so it also catches whatever the fingerprint
 * hasn't thought of.
 *
 * @returns {{ok: boolean, why?: string}}
 */
function joinIsSound(wire, availability, catalogue) {
  const stamped = availability && typeof availability.k === "string";
  if (stamped) {
    const mine = joinFingerprint(wire);
    if (mine !== availability.k) {
      return { ok: false, why: `catalogue ${mine} vs availability ${availability.k}` };
    }
  }

  let performances = 0;
  let withStatus = 0;
  for (const show of catalogue) {
    for (const perf of show.performances || []) {
      performances++;
      if (perf.status) withStatus++;
    }
  }
  if (performances === 0) return { ok: true }; // an empty catalogue is a different problem
/* A festival edition's serving block, turned into what the planning engine plans.
 *
 * `site/data/festivals/<festival>/<edition>.json` is festival-oblivious: every
 * festival's block has the same fields (the contract is scraper/festivals/README.md,
 * enforced by scraper/convert/schema.py). The engine in plan/lib/ speaks the
 * Edinburgh catalogue's vocabulary; this module is the one place the two meet,
 * so a page never sees a serving record and the engine never learns a second
 * shape. The registry `site/data/festivals/index.json` says which festivals and
 * editions exist and where each block lives.
 *
 * An edition's `format` in the registry says which of two shapes its data takes:
 * a serving block ("block"), or the Edinburgh Fringe's own wire files
 * ("edfringe-wire"), which this module adapts to the same result so the pages
 * never learn there are two.
 *
 * Pure apart from the fetches.
 */

import { showUrl } from "./edfringe.js";
import { loadEdfringeWire } from "./edfringe-wire.js";
import { manifestUrlFor } from "./data-cache.js";

export const SCHEMA_VERSION = 1;
export const INDEX_URL = "/data/festivals/index.json";

/* Engine statuses. The engine reads `status` through the Edinburgh denylist, so
 * only a sold-out performance is marked with one that stops it scheduling. A
 * performance no availability source speaks for is "unknown", and unknown
 * means available — the same rule the Edinburgh pages keep — so it is marked
 * on sale, or free to attend when the source says it is free. */
const ENGINE_STATUS = { soldOut: "SOLD_OUT", onSale: "TICKETS_AVAILABLE", free: "FREE_NON_TICKETED" };

/** Fetch the festival registry. */
export async function loadFestivalIndex(url = INDEX_URL) {
  return checkVersion(await getJson(url), url);
}

/** Fetch one edition's block and adapt it. */
export async function loadFestival(url) {
  return adaptFestival(await getJson(url));
}

/**
 * Fetch one edition, whatever its format, and adapt it.
 * @param {object} festivalEntry the registry's festival
 * @param {object} edition one of its editions, with a `dataUrl`
 * @param {{onNote?: (err: unknown, url: string) => void}} [opts]
 */
export async function loadEdition(festivalEntry, edition, { onNote } = {}) {
  if (edition.format === "block") return loadFestival(edition.dataUrl);
  if (edition.format === "edfringe-wire") {
    const { catalogue, lookups } = await loadEdfringeWire(
      {
        catalogue: edition.dataUrl,
        lookups: edition.wire.lookups,
        availability: edition.wire.availability,
        manifest: manifestUrlFor(edition.dataUrl),
      },
      { year: Number(edition.id), onNote }
    );
    return adaptEdfringe({ catalogue, lookups }, festivalEntry, edition);
  }
  throw new Error(`${festivalEntry.id} ${edition.id}: no loader for format ${edition.format}`);
}

/**
 * The edition a reader most likely means on `todayISO`: the one running, else
 * the next to start, else the most recent. Only editions with data count.
 * @returns the edition entry from the registry, or null
 */
export function currentEdition(festivalEntry, todayISO) {
  const loadable = festivalEntry.editions.filter((e) => e.dataUrl);
  if (!loadable.length) return null;
  const running = loadable.find((e) => e.firstDate <= todayISO && todayISO <= e.lastDate);
  if (running) return running;
  const upcoming = loadable.filter((e) => e.firstDate > todayISO).sort((a, b) => a.firstDate.localeCompare(b.firstDate));
  if (upcoming.length) return upcoming[0];
  return [...loadable].sort((a, b) => b.lastDate.localeCompare(a.lastDate))[0];
}

